import React, { useState, useEffect } from "react";
import axios from "axios";
import { Link } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faNotesMedical, faPen, faCheck, faUserPlus, faTooth } from "@fortawesome/free-solid-svg-icons";
import { motion } from "framer-motion";
import "animate.css";
import { API } from "../utils";
import "../styles/main.css";

const PasienList = () => {
  const [pasien, setPasien] = useState([]);
  const [dokterList, setDokterList] = useState([]);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    getPasien();
    getDokter();
  }, []);

  const getPasien = async () => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      const response = await API.get("/pasien", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        withCredentials: true,
      });

      setPasien(response.data);
    } catch (error) {
      console.log(error);
    }
  };

  const getDokter = async () => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      const response = await API.get("/doctor", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        withCredentials: true,
      });
      setDokterList(response.data);
    } catch (error) {
      console.log(error);
    }
  };

  const deletePasien = async (id) => {
    try {
      const token = localStorage.getItem("accessToken");
      if (!token) {
        setMsg("Silakan login terlebih dahulu.");
        return;
      }
      await API.delete(`/pasien/${id}`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
        withCredentials: true,
      });
      getPasien();
    } catch (error) {
      console.log(error);
    }
  };

  const findDokterName = (idDokter) => {
    const dokter = dokterList.find((d) => d.id_dokter === idDokter);
    return dokter ? dokter.nama_dokter : "-";
  };

  return (
    <motion.div
      className="columns mt-5 is-centered"
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
    >
      <div className="column is-full table-container animate__animated animate__fadeInUp">
        <h2 className="title">
          <FontAwesomeIcon icon={faTooth} style={{ marginRight: "10px" }} />
          Daftar Pasien Klinik Gigi
        </h2>

        <Link to={"add"} className="button add-button mb-4">
          <FontAwesomeIcon icon={faUserPlus} style={{ marginRight: "8px" }} />
          Tambah Pasien
        </Link>

        <table className="table is-striped is-fullwidth">
          <thead>
            <tr>
              <th>No</th>
              <th>Nama</th>
              <th>Tanggal Lahir</th>
              <th>Jenis Kelamin</th>
              <th>No. Telepon</th>
              <th>Alamat</th>
              <th>Nama Dokter</th>
              <th>Aksi</th>
            </tr>
          </thead>
          <tbody>
            {pasien.map((item, index) => (
              <motion.tr
                key={item.id}
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.3, delay: index * 0.1 }}
              >
                <td>{index + 1}</td>
                <td>{item.nama}</td>
                <td>{item.tgl_lahir}</td>
                <td>{item.gender}</td>
                <td>{item.no_telp}</td>
                <td>{item.alamat}</td>
                <td>{item.dokter?.nama_dokter || '-'}</td>
                <td>
                  <div className="buttons is-centered">
                    <Link
                      to={`periksa/${item.id}`}
                      className="button is-small is-primary icon-button"
                      title="Periksa"
                    >
                      <FontAwesomeIcon icon={faNotesMedical} />
                    </Link>
                    <Link
                      to={`edit/${item.id}`}
                      className="button is-small is-info icon-button"
                      title="Edit"
                    >
                      <FontAwesomeIcon icon={faPen} />
                    </Link>
                    <button
                      onClick={() => deletePasien(item.id)}
                      className="button is-small is-danger icon-button"
                      title="Selesai"
                    >
                      <FontAwesomeIcon icon={faCheck} />
                    </button>
                  </div>
                </td>
              </motion.tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
};

export default PasienList;
